/** Functional A/A only: existing certified pruning, original native forecast, controlled clock. */
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { appendFileSync, statSync } from "node:fs";
import { createInterface } from "node:readline";
import { gzipSync } from "node:zlib";
import { buildChoice } from "./build-choice";
import { fightNative, hash } from "./native-audit";
import { snapshotBattle } from "./sources/common/src/simulation/battle_snapshot";
import { captureAITargetMemory } from "./sources/common/src/ai/ai";
import { captureDeterministicRandomState } from "./sources/common/src/utils/lib";
import { SearchDriver } from "./sources/common/src/simulation/search_driver";
import { permuteRankedDraftSeed } from "./sources/common/src/simulation/ranked_draft_eval";
import { environment } from "./profiles";
import { V08_A19_PROFILE_SCHEMA } from "./sources/common/src/ai/versions/v0_8_a19_profile";

const [output, statesOutput, implementation] = process.argv.slice(2), g = globalThis as any;
assert(["baseline", "candidate"].includes(implementation));
assert.equal(V08_A19_PROFILE_SCHEMA, "hoc.v0_8_a19_production_profile.v11");
for (const [key, expected] of Object.entries({ SEARCH_ROLLOUTS: "2", SEARCH_HORIZON: "64",
    SEARCH_A19_CERTIFIED_SELECTION_BOUNDS: "1", SEARCH_A19_CERTIFIED_TIGHT_BOUNDS: "1",
    SEARCH_A19_ROLLOUT_ALLOCATION: "uniform", SEARCH_A19_MELEE_BARREL_DELIBERATION: "1" }))
    assert.equal(environment[key], expected);

// Admission proves selection/state equivalence with an unexhausted clock, never runtime improvement.
Object.defineProperty(performance, "now", { configurable: true, writable: true, value: () => 1000 });
assert.equal(performance.now(), 1000);
const proto = SearchDriver.prototype as any, choose = proto.chooseDecision;
const effectiveRollouts = proto.effectiveRollouts, scoreCandidates = proto.scoreCandidates;
const rollout = proto.rollout;
let activeQuery: any;
proto.chooseDecision = function (unit: any, ...args: any[]) {
    if (g.__pruningInFight) {
        g.__rootAux.push({ unitId: unit.getId(), activeUnitId: this.deps.getActiveUnitId(),
            damageStats: normalize(this.deps.captureDamageStats()) });
        if (implementation === "candidate") {
            this.barrelForecastMixture = false;
            this.liveCertifiedBounds = true;
            g.__pruningRoots++;
        }
    }
    return choose.call(this, unit, ...args);
};
proto.effectiveRollouts = function () { return g.__pruningInFight && g.__forceR1 ? 1 : effectiveRollouts.call(this); };
proto.scoreCandidates = function (unit: any, candidates: any[], ...args: any[]) {
    const prior = activeQuery;
    if (g.__pruningInFight) {
        const count = args[2] ?? this.rollouts;
        activeQuery = { ordinal: g.__queryPlans.length, horizon: args[1], rollouts: count,
            turnHorizon: args[4] ?? this.horizon,
            unitId: unit.getId(), seedBase: args[0], catalogSha256: hash(normalize(candidates)),
            indices: new Map(candidates.map((c, i) => [c, i])) };
        g.__queryPlans.push({ ...activeQuery, indices: undefined });
    }
    if (g.__pruningInFight && args[1] === "turns") {
        const count = args[2] ?? this.rollouts;
        assert(Number.isSafeInteger(count) && count >= 1);
        g.__fullQueries[count] = (g.__fullQueries[count] ?? 0) + 1;
    }
    try { return scoreCandidates.call(this, unit, candidates, ...args); }
    finally { activeQuery = prior; }
};
proto.rollout = function (unit: any, candidate: any, ...args: any[]) {
    if (!g.__pruningInFight) return rollout.call(this, unit, candidate, ...args);
    assert(activeQuery && activeQuery.indices.has(candidate));
    const key = hash([activeQuery.ordinal, unit.getId(), activeQuery.indices.get(candidate), args[0], args[1],
        args[2], activeQuery.rollouts, hash(normalize(candidate))]);
    const beforeMemory = hash([...captureAITargetMemory(this.deps.unitsHolder)]);
    const beforeUuid = captureDeterministicRandomState().uuidSequence;
    const actingTeam = unit.getTeam();
    const value = rollout.call(this, unit, candidate, ...args);
    let material: number | null = null;
    const materialCaptured = this.captureA19Material && args[2] === "turns" && Number.isFinite(value);
    if (materialCaptured) {
        // These are exactly the primitive reads the original scoreCandidates performs next.
        // No speculative snapshot or additional mutable-field access is enabled by this observer.
        let ours = 0, enemy = 0;
        for (const remaining of this.deps.unitsHolder.getAllUnits().values()) {
            if (remaining.isDead()) continue;
            const strength = (remaining.getExp() * remaining.getCumulativeHp()) / Math.max(1, remaining.getMaxHp());
            if (remaining.getTeam() === actingTeam) ours += strength; else enemy += strength;
        }
        material = 0.5 * (1 + (ours - enemy) / (ours + enemy + 1000));
    }
    g.__samples.push({ key, score: Number.isFinite(value) ? value : null,
        scoreTag: Number.isFinite(value) ? (Object.is(value, -0) ? "-0" : "finite") : String(value),
        materialCaptured, material, beforeMemory, afterMemory: hash([...captureAITargetMemory(this.deps.unitsHolder)]),
        beforeUuid, afterUuid: captureDeterministicRandomState().uuidSequence });
    return value;
};

function normalize(value: any, seen = new Map<any, number>()): any {
    if (value === undefined) return { $undefined: true };
    if (Object.is(value, -0)) return { $number: "-0" };
    if (typeof value === "number" && !Number.isFinite(value)) return { $number: String(value) };
    if (typeof value === "bigint") return { $bigint: String(value) };
    assert.notEqual(typeof value, "function", "No opaque callable may be silently ignored in a mutable snapshot");
    assert.notEqual(typeof value, "symbol", "No opaque symbol may be silently ignored in a mutable snapshot");
    if (value === null || typeof value !== "object") return value;
    if (seen.has(value)) return { $ref: seen.get(value) };
    const id = seen.size; seen.set(value, id);
    if (value instanceof Map) return { $id: id, $type: "Map", entries: [...value].map(([k, v]) => [normalize(k, seen), normalize(v, seen)]) };
    if (value instanceof Set) return { $id: id, $type: "Set", values: [...value].map(v => normalize(v, seen)) };
    if (ArrayBuffer.isView(value)) return { $id: id, $type: value.constructor.name, values: Array.from(value as any, v => normalize(v, seen)) };
    if (Array.isArray(value)) return { $id: id, $type: "Array", values: Array.from({ length: value.length }, (_, i) =>
        i in value ? normalize(value[i], seen) : { $hole: true }) };
    assert.equal(Object.getOwnPropertySymbols(value).length, 0, "Mutable snapshot symbols need an explicit representation");
    return { $id: id, $type: value.constructor?.name ?? "Object", entries:
        Object.keys(value).map(k => [k, normalize(value[k], seen)]) };
}
let live: any, frames: any[], snapshots: any[], turnHash: ReturnType<typeof createHash>, eventHash: ReturnType<typeof createHash>;
let unitRefs: WeakMap<object, number>, nextUnitRef = 0, snapshotKeys: Set<string>;
function capture(turn: any | null) {
    const snapshot = snapshotBattle(live.unitsHolder, live.grid, live.fightProperties);
    const { unitRefs: currentUnits, ...data } = snapshot;
    const references = [...currentUnits].map(([id, object]) => {
        let token = unitRefs.get(object);
        if (token === undefined) { token = nextUnitRef++; unitRefs.set(object, token); }
        return [id, token, object.constructor.name];
    });
    const state = normalize(data), stateSha256 = hash(state), random = captureDeterministicRandomState();
    const frame = { frame: frames.length, stateSha256, unitReferenceTokens: references,
        targetMemorySha256: hash([...snapshot.aiTargetMemory]), uuidSequence: random.uuidSequence,
        liveRandomDrawCount: g.__auditRng.count, liveRandomPrefixSha256: g.__auditRng.hash.copy().digest("hex"),
        actualTurnPrefixSha256: turnHash.copy().digest("hex"), eventPrefixSha256: eventHash.copy().digest("hex"),
        rawAndChosenShareArray: turn ? turn.rawIncumbent === turn.chosenDecision : null };
    frames.push(frame);
    if (!snapshotKeys.has(stateSha256)) { snapshots.push({ stateSha256, state }); snapshotKeys.add(stateSha256); }
}
g.__pruningCommittedEvent = (r: any) => eventHash.update(JSON.stringify(r));
g.__rushBeforeFight = (context: any) => { live = context; capture(null); };
g.__rushTurn = (r: any) => { turnHash.update(JSON.stringify(r)); capture(r); };
g.__mixtureDecisionCompleted = (o: any) => assert.equal(o.context.a19BarrelIntentForecast, undefined);
const maximumFileBytes = 128 * 1024 * 1024;
function append(path: string, row: any) {
    const raw = gzipSync(JSON.stringify(row) + "\n", { level: 1 });
    let prior = 0; try { prior = statSync(path).size; } catch {}
    assert(prior + raw.length <= maximumFileBytes, "Fixed output byte ceiling; never truncate or retry");
    appendFileSync(path, raw);
}
for await (const line of createInterface({ input: process.stdin })) {
    const { job, registrationSha256 } = JSON.parse(line);
    g.__pruningInFight = false; g.__mode = "stock";
    g.__forceR1 = !!job.forceEffectiveR1;
    g.__pruningRoots = 0; g.__fullQueries = {}; g.__rootAux = []; g.__queryPlans = []; g.__samples = [];
    g.__mixtureLiveMode = false;
    const team = (job.game < 2) === (job.game % 2 === 0) ? 2 : 1;
    const combatSeed = permuteRankedDraftSeed(job.seed + 6 + Number(job.game >= 2));
    const built = buildChoice(job, "current", "current", team);
    assert.equal(hash(built.drafted.config), job.draftConfigSha256[Number(job.game >= 2)]);
    const inputSha256 = hash({ config: built.opening.config, teams: built.opening.teams, terrain: built.opening.terrain, combatSeed });
    if (job.strictOriginalControl) assert.equal(inputSha256, job.reference.inputSha256);
    frames = []; snapshots = []; snapshotKeys = new Set(); unitRefs = new WeakMap(); nextUnitRef = 0;
    turnHash = createHash("sha256"); eventHash = createHash("sha256");
    g.__mixtureLiveMode = !!job.live;
    g.__pruningInFight = true;
    let fought: ReturnType<typeof fightNative>;
    try { fought = fightNative(structuredClone(built.opening), combatSeed); }
    finally { g.__pruningInFight = false; }
    assert.equal(fought.result.endReason, "elimination");
    const score = fought.result.winner === "draw" ? .5 : Number(fought.result.winner === (team === 2 ? "green" : "red"));
    const originalControlApplies = !job.forceEffectiveR1 && job.reference && inputSha256 === job.reference.inputSha256;
    if (job.strictOriginalControl && !job.forceEffectiveR1) assert(originalControlApplies);
    for (const work of fought.quality.work)
        for (const key of ["deadlineFallbacks", "circuitSkipped", "circuitWaitArbitrations", "degradedDecisions"])
            assert.equal(work[key] ?? 0, 0);
    assert((g.__fullQueries[job.forceEffectiveR1 ? 1 : 2] ?? 0) > 0);
    if (implementation === "candidate") assert(g.__pruningRoots > 0);
    const snapshotPayload = { jobId: job.jobId, implementation, snapshots };
    append(statesOutput, snapshotPayload);
    append(output, { ...job, implementation, registrationSha256, inputSha256, traceSha256: fought.traceSha256,
        score, winner: fought.result.winner, originalControlApplies, frames, frameDigest: hash(frames), rootAux: g.__rootAux,
        snapshotPayloadSha256: hash(snapshotPayload), fullQueries: g.__fullQueries, pruningRoots: g.__pruningRoots,
        queryPlans: g.__queryPlans, samples: g.__samples,
        forecastModelChanged: false, realClockTimingClaim: false, quality: fought.quality });
    // Preserve the complete failed observation before a control mismatch stops the attempt.
    if (originalControlApplies) { assert.equal(fought.traceSha256, job.reference.traceSha256); assert.equal(score, job.reference.score); }
    console.log(JSON.stringify({ verified: true, jobId: job.jobId, board: job.board, game: job.game, rows: 1 }));
}

