legacy=p.parent/'barrel-forecast-model-mixture-20261117/v10-functional'
source_seal='1a31dd5fbba8544bf25ad96c3d10ab47165f4ddeabaf8602d9096f83c1dbb3ff'
assert hashlib.sha256((old/'strength-registration.json').read_bytes()).hexdigest()==source_seal
