"""Two fixed fresh-process epochs, two active fights; never retries a failed attempt."""
from pathlib import Path
import concurrent.futures,datetime,hashlib,json,os,queue,shutil,subprocess,threading,time

p=Path(__file__).resolve().parent
raw=(p/'registration.json').read_bytes();reg=json.loads(raw);seal=hashlib.sha256(raw).hexdigest()
old=p.parent/reg['sourceCapsule']
assert hashlib.sha256((old/'strength-registration.json').read_bytes()).hexdigest()==reg['sourceRegistrationSha256']
for f in json.loads((old/'strength-registration.json').read_text())['files']:
 assert hashlib.sha256((old/f['path']).read_bytes()).hexdigest()==f['sha256'],f['path']
for f in reg['files']:assert hashlib.sha256((p/f['path']).read_bytes()).hexdigest()==f['sha256'],f['path']
assert subprocess.check_output(['bun','--version'],text=True).strip()=='1.4.4'
jobs=json.loads((p/'cases.json').read_text());assert len(jobs)==reg['jobsPerEpoch']
out=p/'functional';out.mkdir()
lock=threading.Lock();stop=threading.Event();processes=[];started=time.monotonic()
state={'complete':False,'stage':'starting','epoch':0,'fights':0,'expectedFights':reg['executions'],'errors':[],
       'registrationSha256':seal,'controllerPid':os.getpid(),'absoluteDeadlineEpoch':reg['deadlineUnix']}
def save():
 with lock:
  payload={**state,'elapsedSeconds':round(time.monotonic()-started,3),
           'liveWorkerPids':[proc.pid for proc in processes if proc.poll()is None]}
  f=out/'status.tmp';f.write_text(json.dumps(payload)+'\n');f.replace(out/'status.json')
def halt(reason):
 if stop.is_set():return
 stop.set()
 with lock:state['errors'].append(reason)
 for proc in list(processes):
  if proc.poll()is None:proc.terminate()
remaining=reg['deadlineUnix']-time.time();assert remaining>0
timer=threading.Timer(remaining,lambda:halt('Original functional cutoff reached; no retry/extension'))
timer.daemon=True;timer.start()
def lane(epoch,index,q):
 actors={};logs={}
 try:
  for implementation in ['baseline','candidate']:
   stem=f'e{epoch}-l{index}-{implementation}'
   logs[implementation]=(out/(stem+'.log')).open('x')
   proc=subprocess.Popen(['nice','-n','19','bun','--preload',str(p/implementation/'alias.ts'),
    str(p/implementation/'actor.ts'),str(out/(stem+'.jsonl.gz')),str(out/(stem+'-states.jsonl.gz')),implementation],
    cwd=p,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=logs[implementation],text=True,bufsize=1,
    env={**os.environ,'HOC_A19_CONTEXT_POLICY':'on'})
   actors[implementation]=proc
   with lock:processes.append(proc)
  while not stop.is_set():
   try:base=q.get_nowait()
   except queue.Empty:break
   paths=[False,True]if epoch==0 else[True,False]
   for live in paths:
    implementations=['baseline','candidate']if(base['caseIndex']+epoch+int(live))%2==0 else['candidate','baseline']
    for implementation in implementations:
     assert not stop.is_set()and time.time()<reg['deadlineUnix']
     job={**base,'epoch':epoch,'live':live,'jobId':f"{epoch}/{base['caseId']}/{int(live)}"}
     proc=actors[implementation]
     proc.stdin.write(json.dumps({'job':job,'registrationSha256':seal})+'\n');proc.stdin.flush()
     while True:
      line=proc.stdout.readline()
      if not line:raise RuntimeError(f'{implementation} actor exited at '+job['jobId'])
      try:ack=json.loads(line)
      except json.JSONDecodeError:logs[implementation].write(line);continue
      if isinstance(ack,dict)and ack.get('verified'):break
      logs[implementation].write(line)
     assert ack['jobId']==job['jobId']and ack['rows']==1
     with lock:state['fights']+=1
 finally:
  for proc in actors.values():
   if proc.poll()is None:
    try:proc.stdin.close()
    except BrokenPipeError:pass
  for proc in actors.values():
   if stop.is_set()and proc.poll()is None:proc.terminate()
   result=proc.wait()
   if not stop.is_set():assert result==0
  for log in logs.values():log.close()
try:
 for epoch in range(2):
  state.update({'epoch':epoch,'stage':'functional-cold-epoch'});save()
  q=queue.Queue()
  for job in jobs:q.put(job)
  with concurrent.futures.ThreadPoolExecutor(max_workers=2)as pool:
   futures=[pool.submit(lane,epoch,i,q)for i in range(2)]
   while not all(f.done()for f in futures):
    for f in futures:
     if f.done()and f.exception()is not None:halt(repr(f.exception()))
    if not stop.is_set()and(shutil.disk_usage(p).free<reg['minimumFreeBytes']or sum(f.stat().st_size for f in out.glob('*.gz'))>reg['maximumOutputBytes']):
     halt('Registered disk floor/byte ceiling reached; preserve all output')
    save();time.sleep(3)
   for future in futures:future.result()
  assert not stop.is_set()
 assert state['fights']==reg['executions']and not state['errors']
 state.update({'complete':True,'stage':'awaiting-frozen-verification'})
except BaseException as error:
 halt(repr(error));raise
finally:
 timer.cancel();save()

