 assert row['fullQueries'].get(str(1 if row['forceEffectiveR1']else 2),0)>0
 assert (row['pruningRoots']>0)==(row['implementation']=='candidate')
 assert len({s['key']for s in row['samples']})==len(row['samples'])
 for sample in row['samples']:
  assert sample['scoreTag']in ['finite','-0','-Infinity']
  if sample['scoreTag']=='-Infinity':assert sample['score']is None
  else:assert 0<=sample['score']<=1
  if sample['materialCaptured']:assert 0<=sample['material']<=1
 ref=case_by[row['caseId']]['reference']
 applies=not row['forceEffectiveR1']and row['inputSha256']==ref['inputSha256']
 assert row['originalControlApplies']==applies
 if applies:assert(row['traceSha256'],row['score'])==(ref['traceSha256'],ref['score'])
 if case_by[row['caseId']]['strictOriginalControl']:assert applies
 for field in ['snapshots']:
  assert field in states[key]

def turns(r):return sum(w['rolloutTurnsTotal']for w in r['quality']['work'])
def ordered_subset(a,b):
 index=0
 for x in a:
  while index<len(b)and b[index]['key']!=x['key']:index+=1
  assert index<len(b),('missing or reordered sample',x['key'])
