export function fightNative(opening: any, combatSeed: number) {
    const drivers = new Set<any>(),
        old = SearchDriver.prototype.appliesTo,
        uses: Record<string, number> = {};
    SearchDriver.prototype.appliesTo = function (version: string, team: any) {
        const result = old.call(this, version, team);
        if (result) {
            assert.equal(version, "v0.8");
            uses[team] = (uses[team] ?? 0) + 1;
        }
        if (getA19NeuralState(this)) drivers.add(this);
        return result;
    };
    const turns = createHash("sha256"),
        events = createHash("sha256");
    const strategy = (team: number) => {
        const data = opening.teams[team],
            base = createAIStrategy("v0.8");
        assert(base);
        return {
            version: base.version,
            decideTurn: (u: any, c: any) => base.decideTurn(u, c),
            placeArmy(units: any[]) {
                assert.deepEqual(
                    units.map((u) => [u.getName(), u.getAmountAlive(), u.getFootprintWidth(), u.getFootprintHeight()]),
                    data.bodies,
                );
                return new Map(units.map((u, i) => [u.getId(), data.positions[i]]));
            },
        };
    };
    try {
        const result = withScopedAIEnvironment(
            { V08_A19_SEARCH: "1", V08_A19_SEARCH_ENV_OVERRIDES: JSON.stringify(environment) },
            () =>
                withSearchEnvironment(environment, () =>
                    runMatch({
                        ...opening.config,
                        greenStrategyOverride: strategy(2),
                        redStrategyOverride: strategy(1),
                        researchCaptureDecisionStart: true,
                        decisionObserver: (observation: any) => (globalThis as any).__mixtureDecisionCompleted?.(observation),
                        searchOfflineDeterministicWork: !(globalThis as any).__mixtureLiveMode,
                        headlessEvents: false,
                        beforeFightStart(ctx: any) {
                            for (const team of [2, 1]) {
                                const data = opening.teams[team];
                                assert.deepEqual(
                                    anchors(ctx.unitsHolder.getAllAllies(team)),
                                    data.positions,
                                    "Engine changed native formation",
                                );
                                for (const b of ctx.grid.getArtifactBarrels(team))
                                    assert(ctx.grid.unplaceArtifactBarrel(team, b.index));
                                for (const b of data.barrels)
                                    assert(ctx.grid.placeArtifactBarrel(team, b.index, b.cell));
                            }
                            assert.deepEqual(
                                terrain(ctx.grid.getScatteredMountainsStanding()),
                                terrain(opening.terrain),
                            );
                            const nativeRandom = makeRng(combatSeed);
                            const audit = { count: 0, hash: createHash("sha256") };
                            (globalThis as any).__auditRng = audit;
                            setDeterministicRandomSource(() => {
                                const value = nativeRandom();
                                audit.count++;
                                audit.hash.update(JSON.stringify(value) + "\n");
                                return value;
                            });
                            (globalThis as any).__rushBeforeFight?.(ctx);
                        },
                        turnExecutionObserver: (r: any) => {
                            turns.update(JSON.stringify(r));
                            (globalThis as any).__rushTurn?.(r);
                        },
                        committedEventsObserver: (r: any) => {
                            events.update(JSON.stringify(r));
                            (globalThis as any).__pruningCommittedEvent?.(r);
                        },
                    }),
                ),
        );
        const neural = [...drivers].map((d) => getA19NeuralState(d)!);
        assert(
            !result.rejectedGreen &&
                !result.rejectedRed &&
                [1, 2].every((t) => uses[t] > 0) &&
                neural.length &&
                neural.every((s) => s.modelErrors === 0 && s.missingStart === 0),
            "Invalid authoritative A19 allocation fight",
        );
        return {
            result,
            traceSha256: hash({ turn: turns.digest("hex"), event: events.digest("hex") }),
            quality: {
                rejected: 0,
                searchUses: uses,
                neural,
                work: [...drivers].map((d) => structuredClone(d.counters)),
            },
        };
    } finally {
        SearchDriver.prototype.appliesTo = old;
        setDeterministicRandomSource(undefined);
    }
}

